//
// Root
// Declares CSS custom properties (variables) on the `:root` selector
// for light and dark themes.
//

:root,
[data-bs-theme="light"] {
  // Note: Custom variable values only support SassScript inside `#{}`.

  // Colors
  //
  // Generate palettes for full colors, grays, and theme colors.

  --#{$prefix}body-color: #{$body-color};
  --#{$prefix}body-color-rgb: #{to-rgb($body-color)};
  --#{$prefix}body-bg: #{$body-bg};
  --#{$prefix}body-bg-rgb: #{to-rgb($body-bg)};

  --#{$prefix}emphasis-color: #{$body-emphasis-color};
  --#{$prefix}emphasis-color-rgb: #{to-rgb($body-emphasis-color)};

  --#{$prefix}secondary-color: #{$body-secondary-color};
  --#{$prefix}secondary-bg: #{$body-secondary-bg};
  --#{$prefix}tertiary-color: #{$body-tertiary-color};
  --#{$prefix}tertiary-bg: #{$body-tertiary-bg};

  // Note: --bs-body-color IS generated here, but its usage
  // is limited to the <body> element and elements that explicitly
  // reference var(--bs-body-color). Most Bootstrap components
  // compile their colors from Sass variables at build time,
  // so the CSS custom property is effectively decorative
  // for component-level text colors.

  @each $color, $value in $theme-colors {
    --#{$prefix}#{$color}: #{$value};
    --#{$prefix}#{$color}-rgb: #{to-rgb($value)};
  }

  // Fonts
  //
  --#{$prefix}font-sans-serif: #{inspect($font-family-sans-serif)};
  --#{$prefix}font-monospace: #{inspect($font-family-monospace)};
  --#{$prefix}gradient: #{$gradient};

  // Body
  //
  --#{$prefix}body-font-family: #{inspect($body-font-family)};
  --#{$prefix}body-font-size: #{$body-font-size};
  --#{$prefix}body-font-weight: #{$body-font-weight};
  --#{$prefix}body-line-height: #{$body-line-height};
}

